css:
/* wkhtmltopdf renders this, and it does NOT support flexbox, grid, gap or
   line-clamp. Everything below is table + block layout on purpose. */
.print-format{padding:0!important;margin:0!important;min-height:0!important}

table.qrl{
  width:100mm; height:50mm;
  border:0.8pt solid #000;
  border-collapse:collapse;
  font-family:Helvetica,Arial,sans-serif; color:#000;
  page-break-inside:avoid;
}
table.qrl > tbody > tr > td{border:none; padding:0;}

td.qrl-left{
  width:38mm; text-align:center; vertical-align:middle;
  padding:3mm 1mm 3mm 3mm;
}
.qrl-img{width:32mm; height:32mm; display:block; margin:0 auto;}
.qrl-id{
  display:block; margin-top:1mm;
  font-family:"Courier New",Courier,monospace;
  font-size:8pt; font-weight:bold; letter-spacing:0.2pt; white-space:nowrap;
}

td.qrl-right{vertical-align:middle; padding:3mm 3mm 3mm 1mm;}
.qrl-name{
  font-size:11pt; font-weight:bold; line-height:1.15;
  margin:0 0 1.6mm 0;
}
table.qrl-locwrap{margin:0 0 1.8mm 0;}
td.qrl-loc{
  background:#000; color:#fff;
  padding:1mm 2.4mm;
  font-size:9pt; font-weight:bold; letter-spacing:0.6pt; text-transform:uppercase;
  white-space:nowrap;
}
table.qrl-meta{width:100%; border-collapse:collapse; font-size:7.5pt;}
table.qrl-meta td{border:none; padding:0.35mm 0; vertical-align:top;}
table.qrl-meta td.k{color:#555; width:20mm; white-space:nowrap;}
table.qrl-meta td.v{font-weight:normal;}

html:
{%- set loc  = doc.location or "" -%}
{%- set cat  = doc.asset_category or "" -%}
{%- set cust = doc.custodian or "" -%}
{%- set used = doc.available_for_use_date or doc.purchase_date -%}
<table class="qrl" cellpadding="0" cellspacing="0">
  <tr>
    <td class="qrl-left">
      <img class="qrl-img" src="/files/qr-{{ doc.name }}.png" alt="{{ doc.name }}"><br>
      <span class="qrl-id">{{ doc.name }}</span>
    </td>
    <td class="qrl-right">
      <div class="qrl-name">{{ doc.asset_name }}</div>
      {% if loc %}
      <table cellpadding="0" cellspacing="0" class="qrl-locwrap">
        <tr><td class="qrl-loc">{{ loc }}</td></tr>
      </table>
      {% endif %}
      <table class="qrl-meta" cellpadding="0" cellspacing="0">
        {% if cat %}<tr><td class="k">Category</td><td class="v">{{ cat }}</td></tr>{% endif %}
        <tr><td class="k">Company</td><td class="v">{{ doc.company }}</td></tr>
        {% if cust %}<tr><td class="k">Custodian</td><td class="v">{{ cust }}</td></tr>{% endif %}
        {% if used %}<tr><td class="k">In use from</td><td class="v">{{ frappe.utils.formatdate(used, "dd-MM-yyyy") }}</td></tr>{% endif %}
      </table>
    </td>
  </tr>
</table>
